    "right": "          <div class=\"leaf-body\">\n          <span class=\"roman\">Chapter IV</span>\n          <h2>Written at your own pace</h2>\n          <div class=\"entries\">\n            <article class=\"entry\">\n              <h3>The island is yours <span class=\"hand\">first entry</span></h3>\n              <p>It is generated for you and owned by your wallet, not by a server.</p>\n            </article>\n            <article class=\"entry\">\n              <h3>Sow, then wait <span class=\"hand\">a later page</span></h3>\n              <p>Crops move through their stages from seed to harvest. Check in when it suits you.</p>\n            </article>\n            <article class=\"entry\">\n              <h3>Meet the neighbours <span class=\"hand\">and the next</span></h3>\n              <p>More than 50 creatures, from foxes to kitsune and lantern giraffes. Get to know them slowly. Nothing here is a race.</p>\n            </article>\n            <p class=\"margin-note\">Unclaimed Acres is still in development. These are early pages; more are being written.</p>\n          </div>\n          </div>\n          <div class=\"folio\"><a class=\"turn-link\" href=\"#claim\" data-turn=\"claim\">turn to your page <svg width=\"34\" height=\"18\" viewBox=\"0 0 34 18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" aria-hidden=\"true\"><path d=\"M2 10c8-3 18-4 29-1M25 3c2.5 2 4.5 4 6 6-2.5 1.3-5 3-7 5\"/></svg></a><span>53</span></div>"
